    origin=base.OUT/'friction_single_history_sanity/expanded_width96_fourier';directory=base.OUT/'friction_single_history_sanity/expanded_width96_fourier_refined2000';directory.mkdir(parents=True,exist_ok=True);checkpoint=torch.load(origin/'model.pt',map_location='cpu',weights_only=False);index=json.loads((base.ROOT/'friction/index.json').read_text());row=next(row for row in index['cases'] if row['id']=='friction_001' and row['split']=='train');case=coordinate_inputs(base.read_case(row),checkpoint['coordinate_fourier_frequencies']);norm=checkpoint['normalization'];assert case['npz_sha256']==checkpoint['source_npz_sha256'];model=AbsoluteStateOperator(checkpoint['features'],checkpoint['controls'],checkpoint['outputs'],checkpoint['width'],checkpoint['depth']);model.load_state_dict(checkpoint['state_dict']);optimizer=torch.optim.AdamW(model.parameters(),lr=.0003,weight_decay=0.);b=base.batch([case],norm);weights=base.tensor([3. if group in ['cauchy_stress','interface_shear_traction'] else 1. for group in norm['field_groups']]);updates=0;epoch=0;history=[];started=time.monotonic();initial_metrics=base.field_metrics(base.rollout(model,case,norm),case,norm);best_score=max(group['relative_L2']/group['threshold'] for group in initial_metrics['physical_groups']);best=copy.deepcopy(model.state_dict());best_update=0 # Keep all 1600-update fields and their original gates unchanged while registering the targeted continuation.
