        for step in range(1,case['times']): # Predict all 697 physical entities at every requested history stage.
            prediction,hidden=model(b,previous,hidden,[step]);truth=(base.state_at(b,[step])-b['offset'])/b['scale']*b['mask'];unknown=b['mask']*(1.-base.state_at(b,[step],'prescribed_mask'));per_channel=((prediction-truth)*unknown).square().sum(0)/unknown.sum(0).clamp_min(1.);loss_sum=loss_sum+(per_channel*weights).sum()/weights.sum();steps+=1;previous=prediction # Use only current control inputs and predicted physical/internal histories beyond the initial state.
            if steps==4 or step==case['times']-1: # Preserve the full temporal path while truncating only the gradient tape.
                loss=(loss_sum/steps);loss.backward();torch.nn.utils.clip_grad_norm_(model.parameters(),2.);optimizer.step();updates+=1;rate=.00001+(.0003-.00001)*.5*(1.+math.cos(math.pi*updates/400.)) # Execute and count the actual targeted update.
                for group in optimizer.param_groups: group['lr']=rate # Apply the frozen continuation schedule.
                previous=previous.detach();hidden=hidden.detach();loss_sum=0.;steps=0;optimizer.zero_grad() # Keep the predicted trajectory and GRU memory across each gradient boundary.
